import base64
from PySide6.QtGui import QPixmap

ICON_BASE64_DICT = {
    "CheckBoxFalse": "",
    "CheckBoxTrue": ""
}

def getIcon(key: str) -> QPixmap:
    base64_str = ICON_BASE64_DICT.get(key)
    if not base64_str:
        raise ValueError(f"Значок с ключом \"{key}\" не найден")
    
    icon_bytes = base64.b64decode(base64_str)
    pixmap = QPixmap()
    if not pixmap.loadFromData(icon_bytes):
        raise ValueError(f"Не удалось создать QPixmap из ключа \"{key}\"")
    
    return pixmap